head.script:
scwin.autoComplete1_onviewchange = function(info) {
    //alert("autoComplete1_onviewchange!!!");
    log = "autoComplete1_onviewchange!!!";
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 3. 브라우저에서 autoComplete 를 확인한다.
    //3. Check autoComplete in your browser.
    //Verify 3. 빈값으로 표시된다. (전버전에서는 첫번째 데이터가 표시됨.)
    //3. It is displayed as empty. (In the previous version, the first data is displayed.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1_label').innerText == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. ▼ 버튼을 클릭해서 임의의 데이터를 선택한다.
    //4. Select the desired data by clicking the ▼ button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1_itemTable_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. onviewchange 이벤트가 발생하면서 데이터가 선택된다.
    //4. Data is selected as the onviewchange event occurs.
    WebSquare.wUnit.addCommand("assert", "log", "autoComplete1_onviewchange!!!");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1_label').innerText", "test1");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.a = [];
    for (var i = 1; i <= 8; i++) {
        a.push("test" + i);
        a.push(i);
    }
    dataList1.setData(a);
    autoComplete1.setSelectedIndex(-1);
    window.log = undefined;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 28-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
